<?php
namespace App\Http\Controllers;

use Illuminate\Database\QueryException;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;

class MrmsController extends Controller
{
    public function dashboard() {
        $user = current_user();
        $role = $user['role'];
        $scope = fn ($query) => $query->when($role === 'technician', fn ($q) => $q->where('technician_id', $user['id']));
        $base = DB::table('repairs as r')->join('customers as c','c.id','=','r.customer_id')->join('devices as d','d.id','=','r.device_id')->leftJoin('users as u','u.id','=','r.technician_id')->select('r.*','c.full_name as customer_name','d.brand','d.model','u.name as technician_name');
        if ($role === 'technician') $base->where('r.technician_id', $user['id']);
        $recent = $base->orderByDesc('r.created_at')->limit(8)->get();
        $totalRepairs = $scope(DB::table('repairs'))->count();
        $completed = $scope(DB::table('repairs'))->whereIn('status',['completed','collected'])->count();
        $stats = [
            'customers' => $role === 'technician' ? 0 : DB::table('customers')->count(),
            'pending' => $scope(DB::table('repairs'))->whereNotIn('status',['completed','collected','cancelled'])->count(),
            'completed' => $completed,
            'revenue' => $role === 'technician' ? 0 : DB::table('payments')->whereYear('paid_at',now()->year)->whereMonth('paid_at',now()->month)->sum('amount'),
            'today' => $scope(DB::table('repairs'))->whereDate('created_at',today())->count(),
            'low_stock' => $role === 'admin' ? DB::table('inventory')->whereColumn('quantity','<=','reorder_level')->count() : 0,
            'completion_rate' => $totalRepairs ? round(($completed / $totalRepairs) * 100) : 0,
        ];
        $statuses = $scope(DB::table('repairs'))->select('status',DB::raw('COUNT(*) total'))->groupBy('status')->get();
        $trend = collect(range(6,0))->map(function ($days) use ($scope) {
            $date = today()->subDays($days);
            return (object)['label'=>$date->format('D'),'total'=>$scope(DB::table('repairs'))->whereDate('created_at',$date)->count()];
        });
        return view('dashboard',compact('recent','stats','statuses','trend','role'));
    }
    public function track(Request $r) {
        $repair=null;$history=collect();
        if($r->isMethod('post')){$r->validate(['ticket_no'=>'required','phone'=>'required']);$repair=DB::table('repairs as r')->join('customers as c','c.id','=','r.customer_id')->join('devices as d','d.id','=','r.device_id')->select('r.*','c.full_name as customer_name','d.brand','d.model')->where('r.ticket_no',strtoupper($r->ticket_no))->where('c.phone',$r->phone)->first();if($repair)$history=DB::table('repair_status_history')->where('repair_id',$repair->id)->orderByDesc('created_at')->get();else return back()->withInput()->with('error','No matching repair ticket was found.');}
        return view('track',compact('repair','history'));
    }
    public function customers(Request $r) {
        $q=trim((string)$r->q);$customers=DB::table('customers as c')->leftJoin('devices as d','d.customer_id','=','c.id')->leftJoin('repairs as x','x.customer_id','=','c.id')->select('c.*',DB::raw('COUNT(DISTINCT d.id) device_count'),DB::raw('COUNT(DISTINCT x.id) repair_count'))->when($q,fn($b)=>$b->where(fn($w)=>$w->where('c.full_name','like',"%$q%")->orWhere('c.phone','like',"%$q%")->orWhere('c.email','like',"%$q%")))->groupBy('c.id')->orderByDesc('c.created_at')->get();return view('customers.index',compact('customers','q'));
    }
    public function customerCreate(){return view('customers.form',['customer'=>null]);}
    public function customerStore(Request $r){$v=$r->validate(['full_name'=>'required|max:150','phone'=>'required|max:40','email'=>'nullable|email','address'=>'nullable','brand'=>'required|max:80','model'=>'required|max:100','imei'=>'nullable|max:80','color'=>'nullable|max:50']);try{$id=DB::transaction(function()use($v){$id=DB::table('customers')->insertGetId(['full_name'=>$v['full_name'],'phone'=>$v['phone'],'email'=>$v['email']?:null,'address'=>$v['address']?:null,'created_at'=>now(),'updated_at'=>now()]);DB::table('devices')->insert(['customer_id'=>$id,'brand'=>$v['brand'],'model'=>$v['model'],'imei'=>$v['imei']?:null,'color'=>$v['color']?:null,'created_at'=>now()]);return $id;});log_activity('create','customer',$id,'Registered customer '.$v['full_name']);return redirect()->route('customers.show',$id)->with('success','Customer and device registered successfully.');}catch(QueryException){return back()->withInput()->with('error','Phone, email, or IMEI may already exist.');}}
    public function customerShow(int $id){$customer=DB::table('customers')->find($id);abort_unless($customer,404);$devices=DB::table('devices')->where('customer_id',$id)->orderByDesc('created_at')->get();$repairs=DB::table('repairs as r')->join('devices as d','d.id','=','r.device_id')->leftJoin('users as u','u.id','=','r.technician_id')->select('r.*','d.brand','d.model','u.name as technician_name')->where('r.customer_id',$id)->orderByDesc('r.created_at')->get();return view('customers.show',compact('customer','devices','repairs'));}
    public function customerDevice(Request $r,int $id){$v=$r->validate(['brand'=>'required','model'=>'required','imei'=>'nullable','color'=>'nullable']);try{DB::table('devices')->insert(['customer_id'=>$id,'brand'=>$v['brand'],'model'=>$v['model'],'imei'=>$v['imei']?:null,'color'=>$v['color']?:null,'created_at'=>now()]);return back()->with('success','Device added successfully.');}catch(QueryException){return back()->with('error','IMEI may already exist.');}}
    public function customerEdit(int $id){$customer=DB::table('customers')->find($id);abort_unless($customer,404);return view('customers.form',compact('customer'));}
    public function customerUpdate(Request $r,int $id){$v=$r->validate(['full_name'=>'required','phone'=>'required','email'=>'nullable|email','address'=>'nullable']);DB::table('customers')->where('id',$id)->update(array_merge($v,['email'=>$v['email']?:null,'address'=>$v['address']?:null,'updated_at'=>now()]));log_activity('update','customer',$id,'Updated customer details');return redirect()->route('customers.show',$id)->with('success','Customer updated successfully.');}
    public function repairs(Request $r){$q=trim((string)$r->q);$status=trim((string)$r->status);$repairs=DB::table('repairs as x')->join('customers as c','c.id','=','x.customer_id')->join('devices as d','d.id','=','x.device_id')->leftJoin('users as u','u.id','=','x.technician_id')->select('x.*','c.full_name as customer_name','c.phone as customer_phone','d.brand','d.model','u.name as technician_name')->when(is_role('technician'),fn($b)=>$b->where('x.technician_id',current_user()['id']))->when($q,fn($b)=>$b->where(fn($w)=>$w->where('x.ticket_no','like',"%$q%")->orWhere('c.full_name','like',"%$q%")->orWhere('c.phone','like',"%$q%")->orWhere('d.brand','like',"%$q%")->orWhere('d.model','like',"%$q%")))->when($status,fn($b)=>$b->where('x.status',$status))->orderByDesc('x.created_at')->get();return view('repairs.index',compact('repairs','q','status'));}
    public function repairCreate(Request $r){$customers=DB::table('customers')->orderBy('full_name')->get();$devices=DB::table('devices as d')->join('customers as c','c.id','=','d.customer_id')->select('d.*','c.full_name as customer_name')->orderBy('c.full_name')->get();$technicians=DB::table('users')->where('role','technician')->where('status','active')->orderBy('name')->get();$selectedCustomer=(int)$r->customer_id;return view('repairs.form',compact('customers','devices','technicians','selectedCustomer'));}
    public function repairStore(Request $r){$v=$r->validate(['customer_id'=>'required|integer','device_id'=>'required|integer','technician_id'=>'nullable|integer','fault_description'=>'required','estimated_cost'=>'required|numeric|min:0','priority'=>'required|in:low,normal,high,urgent','expected_date'=>'nullable|date']);abort_unless(DB::table('devices')->where('id',$v['device_id'])->where('customer_id',$v['customer_id'])->exists(),422);$ticket=generate_code('MR');$id=DB::table('repairs')->insertGetId(array_merge($v,['ticket_no'=>$ticket,'technician_id'=>$v['technician_id']?:null,'expected_date'=>$v['expected_date']?:null,'status'=>'pending','created_by'=>current_user()['id'],'created_at'=>now(),'updated_at'=>now()]));DB::table('repair_status_history')->insert(['repair_id'=>$id,'status'=>'pending','note'=>'Repair ticket created','changed_by'=>current_user()['id'],'created_at'=>now()]);create_notification($id,(int)$v['customer_id'],"Repair ticket $ticket created","Your repair ticket $ticket has been created. Current status: Pending.");log_activity('create','repair',$id,"Created ticket $ticket");return redirect()->route('repairs.show',$id)->with('success',"Repair ticket $ticket created successfully.");}
    private function repairQuery(){return DB::table('repairs as r')->join('customers as c','c.id','=','r.customer_id')->join('devices as d','d.id','=','r.device_id')->leftJoin('users as u','u.id','=','r.technician_id')->leftJoin('users as creator','creator.id','=','r.created_by')->select('r.*','c.full_name as customer_name','c.phone as customer_phone','c.email as customer_email','c.address as customer_address','d.brand','d.model','d.imei','d.color','u.name as technician_name','creator.name as created_by_name');}
    public function repairShow(int $id){$repair=$this->repairQuery()->where('r.id',$id)->first();abort_unless($repair,404);abort_if(is_role('technician')&&(int)$repair->technician_id!==(int)current_user()['id'],403);$history=DB::table('repair_status_history as h')->leftJoin('users as u','u.id','=','h.changed_by')->select('h.*','u.name as changed_by_name')->where('h.repair_id',$id)->orderByDesc('h.created_at')->get();$parts=DB::table('repair_parts as rp')->join('inventory as i','i.id','=','rp.inventory_id')->select('rp.*','i.part_name','i.sku')->where('rp.repair_id',$id)->get();$inventory=is_role('admin')?DB::table('inventory')->where('quantity','>',0)->orderBy('part_name')->get():collect();$invoice=DB::table('invoices')->where('repair_id',$id)->first();return view('repairs.show',compact('repair','history','parts','inventory','invoice'));}
    public function repairEdit(int $id){$repair=$this->repairQuery()->where('r.id',$id)->first();abort_unless($repair,404);abort_if(is_role('technician')&&(int)$repair->technician_id!==(int)current_user()['id'],403);$technicians=DB::table('users')->where('role','technician')->where('status','active')->get();return view('repairs.update',compact('repair','technicians'));}
    public function repairUpdate(Request $r,int $id){$repair=DB::table('repairs')->find($id);abort_unless($repair,404);abort_if(is_role('technician')&&(int)$repair->technician_id!==(int)current_user()['id'],403);$v=$r->validate(['status'=>'required|in:pending,under_diagnosis,repairing,waiting_parts,completed,collected,cancelled','diagnosis'=>'nullable','labor_cost'=>'required|numeric|min:0','note'=>'nullable','technician_id'=>'nullable|integer']);$parts=(float)DB::table('repair_parts')->where('repair_id',$id)->selectRaw('COALESCE(SUM(quantity*unit_price),0) total')->value('total');$update=['status'=>$v['status'],'diagnosis'=>$v['diagnosis'],'labor_cost'=>$v['labor_cost'],'parts_cost'=>$parts,'total_cost'=>$parts+(float)$v['labor_cost'],'updated_at'=>now()];if(!is_role('technician'))$update['technician_id']=$v['technician_id']?:null;if($v['status']==='completed')$update['completed_at']=now();DB::transaction(function()use($id,$v,$update,$repair){DB::table('repairs')->where('id',$id)->update($update);if($repair->status!==$v['status']||$v['note'])DB::table('repair_status_history')->insert(['repair_id'=>$id,'status'=>$v['status'],'note'=>$v['note']?:'Status updated','changed_by'=>current_user()['id'],'created_at'=>now()]);});if($repair->status!==$v['status'])create_notification($id,(int)$repair->customer_id,"Repair {$repair->ticket_no} status updated",'Your device repair is now '.ucwords(str_replace('_',' ',$v['status'])).'.');return redirect()->route('repairs.show',$id)->with('success','Repair updated successfully.');}
    public function addPart(Request $r,int $id){$v=$r->validate(['inventory_id'=>'required|integer','quantity'=>'required|integer|min:1']);try{DB::transaction(function()use($id,$v){$item=DB::table('inventory')->where('id',$v['inventory_id'])->lockForUpdate()->first();abort_unless($item&&$item->quantity>=$v['quantity'],422,'Insufficient stock.');DB::table('repair_parts')->insert(['repair_id'=>$id,'inventory_id'=>$item->id,'quantity'=>$v['quantity'],'unit_price'=>$item->unit_price,'created_at'=>now()]);DB::table('inventory')->where('id',$item->id)->decrement('quantity',$v['quantity']);$parts=(float)DB::table('repair_parts')->where('repair_id',$id)->selectRaw('SUM(quantity*unit_price) total')->value('total');$labor=(float)DB::table('repairs')->where('id',$id)->value('labor_cost');DB::table('repairs')->where('id',$id)->update(['parts_cost'=>$parts,'total_cost'=>$parts+$labor]);});return back()->with('success','Spare part added and stock reduced.');}catch(QueryException){return back()->with('error','Could not add the spare part.');}}
    public function inventory(Request $r){$q=trim((string)$r->q);$items=DB::table('inventory')->when($q,fn($b)=>$b->where(fn($w)=>$w->where('part_name','like',"%$q%")->orWhere('sku','like',"%$q%")->orWhere('category','like',"%$q%")))->orderBy('part_name')->get();$stockValue=(float)DB::table('inventory')->selectRaw('COALESCE(SUM(quantity*unit_price),0) total')->value('total');$lowStock=DB::table('inventory')->whereColumn('quantity','<=','reorder_level')->count();return view('inventory',compact('items','q','stockValue','lowStock'));}
    public function inventoryStore(Request $r){if($r->action==='adjust'){$v=$r->validate(['id'=>'required|integer','change'=>'required|integer']);DB::update('UPDATE inventory SET quantity=GREATEST(0,quantity+?) WHERE id=?',[$v['change'],$v['id']]);return back()->with('success','Stock quantity adjusted.');}$v=$r->validate(['part_name'=>'required','sku'=>'required','category'=>'nullable','quantity'=>'required|integer|min:0','reorder_level'=>'required|integer|min:0','unit_price'=>'required|numeric|min:0']);try{DB::table('inventory')->insert(array_merge($v,['sku'=>strtoupper($v['sku']),'category'=>$v['category']?:'Other','created_at'=>now(),'updated_at'=>now()]));return back()->with('success','Inventory item added.');}catch(QueryException){return back()->withInput()->with('error','SKU must be unique.');}}
}
